# "New agent here" is a draft until the first message, and that message
# creates the workspace WITH the prompt -- so the daemon names it.
#
# The regression: the plugin created the workspace bare and the agent after it,
# so every workspace started from the editor stayed `main` in the app's
# sidebar and on the rail.
#
# The title is generated by the daemon's own small model call. Against a
# daemon with no working provider it falls back to the prompt's first line --
# either way it is not the branch name, which is what this asserts.
source "$(dirname "$0")/../lib.sh"

repo="$(fresh_repo)"

workspaces_in() {
  "$D" paseo workspace ls --json 2>/dev/null |
    python3 -I -c "import json,sys; print(json.dumps([w for w in json.load(sys.stdin) if w.get('cwd') == sys.argv[1]]))" "$1"
}

"$E" stop
"$E" start "$repo"
"$E" keys ':Paseo chat' Enter
# Nothing here yet: the new-task screen, on a chat here (nothing remembered).
new_task_ready

# A draft creates nothing on the daemon.
[ "$(workspaces_in "$repo")" = "[]" ] || fail "the draft created a workspace: $(workspaces_in "$repo")"

users_before=0
"$E" keys 'Fix the flaky login test on CI' Escape Enter
wait_idle 40

[ "$(workspaces_in "$repo" | python3 -I -c 'import json,sys; print(len(json.load(sys.stdin)))')" = "1" ] \
  || fail "expected one workspace: $(workspaces_in "$repo")"

# Named from the prompt, not the branch. Generation runs after creation.
for _ in $(seq 1 60); do
  name="$(workspaces_in "$repo" | python3 -I -c 'import json,sys; print(json.load(sys.stdin)[0]["name"])')"
  [ "$name" != "main" ] && break
  sleep 0.5
done
[ "$name" != "main" ] || fail "workspace still called main"
echo "  titled: $name"

# The rail shows it by that name without being asked again.
"$E" wait "vim.iter(vim.api.nvim_list_bufs()):any(function(b) return vim.bo[b].filetype == \"paseo-rail\" and table.concat(vim.api.nvim_buf_get_lines(b, 0, -1, false), \" \"):find(\"login\", 1, true) ~= nil end)" 15 \
  || fail "the rail does not show the titled workspace"

# And the first thought is one block, even though history and live met in it.
turn='[b["kind"] for b in s["blocks"][max(i for i,b in enumerate(s["blocks"]) if b["kind"]=="user")+1:]]'
[ "$(q "$turn.count(\"thinking\")")" = "1" ] || fail "thinking split across the seam: $(q "$turn")"
"$E" shot start-here >/dev/null
